import json

# Regenerate the output grid
H, W = 17, 19
keys = [(3, 4), (8, 11), (13, 6)]
grid_center = (W - 1) / 2  # 9.0
right_belt_center = 5  # Right half pattern center
left_belt_center = 11  # Left half pattern center

def get_pattern_col(c):
    if c >= grid_center:
        return right_belt_center
    else:
        return left_belt_center

output = [[0]*W for _ in range(H)]

# Set key values - the input keys become 3
for r, c in keys:
    output[r][c] = 3

# Generate patterns for each key
for r, c in keys:
    pcol = get_pattern_col(c)
    pcol_start = pcol - 2
    pat_row_3 = r - 1

    for pr in range(5):
        grid_row = pat_row_3 - 2 + pr
        for pc in range(pcol_start, pcol_start + 5):
            if grid_row < 0 or grid_row >= H or pc < 0 or pc >= W:
                continue

            rel_row = pr - 2
            rel_col = pc - pcol

            if rel_row == -2:
                output[grid_row][pc] = 5
            elif rel_row == -1:
                output[grid_row][pc] = 2 if rel_col in (-2, 2) else 5
            elif rel_row == 0:
                output[grid_row][pc] = 3 if rel_col == 0 else (2 if rel_col in (-2, 2) else 0)
            elif rel_row == 1:
                output[grid_row][pc] = 2 if rel_col in (-2, 2) else 0
            elif rel_row == 2:
                output[grid_row][pc] = 8 if rel_col in (-2, 0, 2) else 2

# Add hinge extensions for right-half patterns
for r, c in keys:
    if c >= grid_center:
        pat_row_3 = r - 1
        pcol = get_pattern_col(c)
        hinge_row = pat_row_3 + 2
        for pc in range(pcol + 3, min(pcol + 7, W)):
            if 0 <= hinge_row < H:
                output[hinge_row][pc] = 8
        output[hinge_row][pcol + 2] = 2

# Submit
action = {"action": "submit", "grid": output}

print(json.dumps(action))

